/* The N5 course is part of the regular study archive. Authentic tests remain separate. */
const N5_STAGES=['words1','words2','grammar','reading','listening','review'];
const N5_STAGE_NAMES={words1:'词汇 · 前 10 个',words2:'词汇 · 后 10 个',grammar:'三节语法与例句',reading:'课文阅读 · 三题',listening:'场景听力 · 三题',review:'单元复习 · 10 题',final:'N5 结课测评 · 40 题',reviewWords:'到期旧词复习 · 最多 5 个'};
const n5Unit=id=>N5_UNITS.find(u=>u.id===id);
function n5Questions(u,stage){if(stage==='grammar')return u.grammarIds;if(stage==='reading'||stage==='listening')return u[stage].ids;return [...u.grammarIds,...u.reading.ids,...u.listening.ids,u.wordIds[0]];}
function n5UnitState(id){state.course??={units:{},kanji:[],checks:{},exam:null};return state.course.units[id]??={done:[],ratings:[],answers:{},review:{},draft:'',score:0};}
const cleanBeforeN5=cleanState;
cleanState=function(raw){const s=cleanBeforeN5(raw),c=raw.course||{};s.course={units:{},kanji:[...new Set((Array.isArray(c.kanji)?c.kanji:[]).filter(k=>N5_REFERENCE.kanji.some(x=>x.char===k)))],checks:{},exam:null};
 for(const u of N5_UNITS){const v=c.units?.[u.id];if(!v)continue;const all=n5Questions(u,'review'),answers={},review={};for(const [id,a]of Object.entries(v.answers||{}))if(all.includes(id)&&Number.isInteger(a)&&a>=0&&a<questionById(id).options.length)answers[id]=a;for(const [id,a]of Object.entries(v.review||{}))if(all.includes(id)&&Number.isInteger(a)&&a>=0&&a<questionById(id).options.length)review[id]=a;
  s.course.units[u.id]={done:[...new Set((Array.isArray(v.done)?v.done:[]).filter(x=>N5_STAGES.includes(x)))],ratings:[...new Set((Array.isArray(v.ratings)?v.ratings:[]).filter(id=>u.wordIds.includes(id)))],answers,review,draft:String(v.draft||'').slice(0,4000),score:num(v.score,100)};
 }
 for(const key of ['1','2','3','4','final'])if(c.checks?.[key]&&dateValid(c.checks[key].date))s.course.checks[key]={score:num(c.checks[key].score,100),date:c.checks[key].date};
 const x=c.exam;if(x&&['1','2','3','4','final'].includes(x.key)&&Array.isArray(x.ids)&&x.ids.length>0&&x.ids.length<=40&&x.ids.every(id=>questionById(id)?.level==='N5')){const answers={};for(const [id,a]of Object.entries(x.answers||{}))if(x.ids.includes(id)&&Number.isInteger(a)&&a>=0&&a<questionById(id).options.length)answers[id]=a;s.course.exam={key:x.key,ids:x.ids,answers,submitted:!!x.submitted};}
 if(s.guide.day&&n5Unit(raw.guide?.day?.n5Unit)&&Array.isArray(raw.guide.day.n5Stages)&&raw.guide.day.n5Stages.length===s.guide.day.steps.length&&raw.guide.day.n5Stages.every((k,i)=>(N5_STAGES.includes(k)||k==='final'||k==='reviewWords')&&s.guide.day.steps[i].kind===(k==='reviewWords'?'vocab':'course'))){s.guide.day.n5Unit=raw.guide.day.n5Unit;s.guide.day.n5Stages=raw.guide.day.n5Stages;}
 if(s.guide.day?.steps.some(t=>t.kind==='course')&&!s.guide.day.n5Unit)s.guide.day=null;
 s.course.legacyDraft=String(c.legacyDraft||'').slice(0,4000);
 s.course.cursor={unit:n5Unit(c.cursor?.unit)?c.cursor.unit:null,stage:N5_STAGES.includes(c.cursor?.stage)?c.cursor.stage:"words1",tab:["course","kanji","sound","checks"].includes(c.cursor?.tab)?c.cursor.tab:"course"};
 return s;
};
try{const saved=startupStudyRecord||JSON.parse(localStorage.getItem('hajime-study-v2')||'null');state=cleanState({...state,course:saved?.course,guide:saved?.guide||state.guide});}catch{state=cleanState(state);}
let n5Selected=state.course.cursor?.unit||null,n5Stage=state.course.cursor?.stage||'words1',n5Tab=state.course.cursor?.tab||'course',n5Search='';
const persistBeforeN5=persist;
persist=function(){state.course.cursor={unit:n5Selected,stage:n5Stage,tab:n5Tab};persistBeforeN5();};
const n5NextUnit=()=>N5_UNITS.find(u=>!n5UnitState(u.id).done.includes('review'))||N5_UNITS.at(-1);
const n5Passed=()=>N5_UNITS.filter(u=>n5UnitState(u.id).done.includes('review')).length;
function n5Status(u){const s=n5UnitState(u.id);return s.done.includes('review')?'✓ 单元通过':s.done.length||s.ratings.length||Object.keys(s.answers).length?'◐ 学习中':'○ 未开始';}
function n5Tabs(){return `<div class="n5-tabs" role="group" aria-label="N5课程内容">${[['course','24 单元课程'],['kanji','基础汉字'],['sound','发音专题'],['checks','复习与结课']].map(([k,t])=>`<button class="chip ${n5Tab===k?'selected':''}" data-n5tab="${k}" aria-pressed="${n5Tab===k}">${t}</button>`).join('')}</div>`;}
function n5Overview(){const next=n5NextUnit();return `<div class="n5-course-hero"><div><span class="label">从零基础，到独立读懂简单日语</span><h2>N5 系统课程</h2><p>24 个生活场景，把词汇、句型和课文一起学。先完成五十音，再按单元逐步推进。</p><button class="primary" data-n5unit="${next.id}">继续第 ${N5_UNITS.indexOf(next)+1} 单元 →</button><button class="secondary" data-page="plan">按每日计划学习 →</button></div><div class="n5-course-numbers"><b>${n5Passed()}<small> / 24 单元通过</small></b><span>72 节语法讲解 · 48 篇课文 / 听力<br>${lw('N5').length} 张词卡 · ${N5_REFERENCE.kanji.length} 个基础汉字</span></div></div><div class="n5-scope">本课程按初级日语能力组织，N5 为学习目标；没有官方固定语法、词汇清单。后几单元包含衔接 N4 的基础扩展，已在讲解中提示。课程通过与考试合格分别判断。</div><div class="beginner-route">${['词汇认读','语法与例句','课文 + 听力','单元复习'].map((t,i)=>`<div><b>0${i+1}</b><span>${t}</span></div>`).join('')}</div>${N5_UNITS.reduce((html,u,i)=>html+(i%6===0?`<div class="sectionhead"><h2>阶段 ${i/6+1} <small>${['建立基本句子','描述生活与比较','动词变化与行动','读懂完整表达'][i/6]}</small></h2></div><div class="n5-unit-grid">`:'')+`<button class="n5-unit-card ${n5UnitState(u.id).done.includes('review')?'passed':u.id===next.id?'recommended':''}" data-n5unit="${u.id}"><div><span class="label">UNIT ${String(i+1).padStart(2,'0')}</span><span class="n5-badge">${n5Status(u)}</span></div><h3>${esc(u.title)}</h3><p>${esc(u.goal)}</p><small>20 词 · 3 节语法 · 阅读 / 听力各 3 题</small><div class="bar"><div style="width:${n5UnitState(u.id).done.length/6*100}%"></div></div><span class="more">${u.id===next.id?'推荐下一课':'打开单元'} →</span></button>`+(i%6===5?`</div><button class="secondary n5-block-check" data-n5exam="${(i+1)/6}">第 ${i-4}–${i+1} 单元复习 · 20 题 →</button>`:''), '')}`;}
function n5QuestionHtml(id,review=false){const q=questionById(id),s=n5UnitState(n5Selected),map=review?s.review:s.answers,a=map[id],answered=Number.isInteger(a);return `<article class="n5-question"><span class="label">${typeNames[q.type]} · ${esc(q.title)}</span>${review&&q.type==='reading'?`<p class="japanese-text" lang="ja">${esc(q.text)}</p>`:''}${review&&q.type==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放题目</button><details><summary>听后查看原文</summary><p lang="ja">${esc(q.text)}</p></details>`:''}<h3>${esc(q.q)}</h3><div class="answers">${q.options.map((o,i)=>`<button data-n5answer="${id}" data-value="${i}" ${review?'data-review="true"':''} ${answered?'disabled':''} class="${answered&&i===q.answer?'correct':answered&&a===i?'wrong':''}">${esc(o)}</button>`).join('')}</div>${answered?`<p class="feedback">${a===q.answer?'✓ 正确。':'✕ 再理解一次：'} ${esc(q.why)}</p>`:''}</article>`;}
function n5WordStage(u){const start=n5Stage==='words1'?0:10,s=n5UnitState(u.id);return `<p class="hint">先回忆读音和词义，再展开核对。罗马音可在页面顶部隐藏；长音保留 ou、ei 或重复元音，需读足拍数。每个词都自评一次后完成本步；不熟悉的词会留在今日复习中。</p><div class="n5-word-progress"><span id="n5WordProgress" role="status">已自评 ${u.wordIds.slice(start,start+10).filter(id=>s.ratings.includes(id)).length} / 10 个</span><button class="secondary" id="n5NextWord" ${u.wordIds.slice(start,start+10).every(id=>s.ratings.includes(id))?'disabled':''}>下一个待认读 →</button></div><div class="n5-word-grid">${u.wordIds.slice(start,start+10).map(id=>{const w=words.find(w=>w.id===id);return `<article class="n5-word" data-word-id="${id}"><span class="n5-badge">${s.ratings.includes(id)?'✓ 已复习':'○ 待认读'}</span><h3 lang="ja">${esc(w.word)}</h3><details data-expand-reading="${esc(w.reading)}"><summary>展开读音与词义 <small class="expand-audio-hint">· 自动读一次</small></summary><p lang="ja">${esc(w.reading)}</p>${romanLine(w.reading)}<div class="vocab-definition"><p class="vocab-meaning"><span class="vocab-field">词义</span><strong>${esc(w.meaning)}</strong></p><p class="vocab-pos"><span class="vocab-field">词性</span><span class="pos-badge">${esc(w.pos)}</span></p></div><button class="secondary" data-speak="${esc(w.reading)}">▷ 听读音</button><div class="toolbar"><button class="secondary" data-n5rate="${id}" data-value="0">还不熟</button><button class="primary" data-n5rate="${id}" data-value="1">记住了 ✓</button></div></details></article>`;}).join('')}</div>`;}
function n5GrammarStage(u){return u.grammar.map((g,i)=>`<article class="n5-grammar"><span class="label">句型 ${i+1} / 3</span><h2>${esc(g.title)}</h2><h3>规则与接续</h3><p class="n5-rule">${esc(g.rule)}</p>${g.examples.map(([ja,kana,zh])=>`<div class="example"><b lang="ja">${esc(ja)}</b><button class="speak" data-speak="${esc(ja)}">▷ 跟读</button><small lang="ja">${esc(kana)}</small>${romanLine(kana,true)}<p>${esc(zh)}</p></div>`).join('')}<div class="hint"><strong>容易混淆的地方</strong><p>${esc(g.pitfall)}</p></div>${n5QuestionHtml(u.grammarIds[i])}</article>`).join('');}
function n5TextStage(u){const t=u[n5Stage],listen=n5Stage==='listening';const original=`<p class="japanese-text" lang="ja">${esc(t.text).replaceAll('\n','<br>')}</p><details><summary>查看假名、罗马音与中文对照</summary><p class="japanese-text" lang="ja">${esc(t.kana)}</p>${romanLine(t.kana,true)}<p>${esc(t.translation)}</p></details>`;return `<article class="n5-text"><span class="label">${listen?'先听两遍，再回答':'先不看翻译，定位时间、人物与动作'}</span><h2>${esc(t.title)}</h2>${listen?`<div class="audio-controls"><button class="primary" data-n5audio="${u.id}">▷ 播放场景对话</button><label>语速<select id="n5Speed"><option value="0.75">慢速</option><option value="0.95" selected>标准</option></select></label><button class="secondary" data-stop-audio="true">停止</button></div><p class="completion-note">按角色播放台词，不读角色标签。可在顶部语音设置选择角色 A / B 的声音；只有一个声音时用音高区分。请同时用独立真题训练里的官方真人录音练习。</p><details><summary>听后展开原文</summary>${original}</details>`:original}${t.ids.map(id=>n5QuestionHtml(id)).join('')}</article>`;}
function n5ReviewStage(u){const s=n5UnitState(u.id),ids=n5Questions(u,'review'),done=ids.every(id=>Number.isInteger(s.review[id])),score=done?Math.round(ids.filter(id=>s.review[id]===questionById(id).answer).length/ids.length*100):0;return `<div class="hint">本组 10 题覆盖本单元句型、词汇、阅读与听力。全部作答且正确率达到 80% 后通过；未达到时可重新练习。</div>${done?`<div class="n5-review-score"><b>${score}%</b><p>${score>=80?'✓ 达到本单元通过要求':'继续复习错题，再试一次'}</p></div>`:''}${ids.map(id=>n5QuestionHtml(id,true)).join('')}`;}
function n5CanFinish(u,stage){const s=n5UnitState(u.id);if(stage==='words1'||stage==='words2'){const start=stage==='words1'?0:10;return u.wordIds.slice(start,start+10).every(id=>s.ratings.includes(id));}const ids=n5Questions(u,stage),a=stage==='review'?s.review:s.answers;if(!ids.every(id=>Number.isInteger(a[id])))return false;return stage!=='review'||(N5_STAGES.slice(0,5).every(k=>s.done.includes(k))&&ids.filter(id=>a[id]===questionById(id).answer).length/ids.length>=.8);}
function n5Writing(u){const s=n5UnitState(u.id);return `<details class="writing-panel"><summary>✎ 单元写作 · 可选</summary><p>${esc(u.writing.prompt)}</p><label>我的日语草稿<textarea id="n5Writing" maxlength="4000" placeholder="写 2–4 句与自己有关的话…">${esc(s.draft)}</textarea></label><small id="n5WritingStatus" role="status">自动保存在本单元，不影响必修进度。</small><details><summary>参考表达与自查</summary><p lang="ja">${esc(u.writing.sample)}</p><p>${esc(u.writing.check)}</p><small>参考用于对照，暂不自动评分。</small></details></details>`;}
function n5UnitView(){const u=n5Unit(n5Selected);if(!u){n5Selected=null;return n5Overview();}const s=n5UnitState(u.id),index=N5_UNITS.indexOf(u),can=n5CanFinish(u,n5Stage);return `<div class="toolbar"><button class="secondary" id="n5Back">← 全部单元</button><button class="secondary" data-page="plan">返回每日计划 →</button></div><div class="n5-unit-heading"><div><span class="label">第 ${index+1} / 24 单元</span><h2>${esc(u.title)}</h2><p>${esc(u.goal)}</p></div><span class="n5-badge">${n5Status(u)}</span></div><div class="n5-stage-tabs" role="group" aria-label="单元学习步骤">${N5_STAGES.map((k,i)=>`<button class="${n5Stage===k?'selected':''} ${s.done.includes(k)?'done':''}" data-n5stage="${k}" aria-pressed="${n5Stage===k}"><b>${s.done.includes(k)?'✓':i+1}</b>${N5_STAGE_NAMES[k]}</button>`).join('')}</div><div class="n5-stage-body">${n5Stage.startsWith('words')?n5WordStage(u):n5Stage==='grammar'?n5GrammarStage(u):n5Stage==='review'?n5ReviewStage(u):n5TextStage(u)}</div><div class="n5-finish"><p>${s.done.includes(n5Stage)?'✓ 本步已完成，可以复习或继续。':can?'已完成本步练习，确认后继续。':'完成本步练习后继续；单元复习需达到 80%。'}</p><button class="primary" id="n5Finish" ${!can?'disabled':''}>${n5Stage==='review'?'记录单元通过 ✓':'完成本步，继续 →'}</button>${!n5Stage.startsWith('words')?'<button class="secondary" id="n5Retry">清空本步答案，重新练习</button>':''}</div>${s.done.includes('review')?`<div class="hint">✓ 单元复习 ${s.score}% · ${index<23?`<button class="primary" data-n5unit="${N5_UNITS[index+1].id}">进入第 ${index+2} 单元 →</button>`:'<button class="primary" data-n5exam="final">开始 N5 结课测评 →</button>'}</div>`:''}${n5Writing(u)}`;}
function n5KanjiView(){const chars=N5_REFERENCE.kanji.filter(k=>[k.char,k.meaning,...k.words.flat()].some(x=>String(x).includes(n5Search)));return `<div class="sectionhead"><h2>基础汉字 · ${N5_REFERENCE.kanji.length} 字</h2><span>已练习 ${state.course.kanji.length} 字</span></div><label class="n5-search">查找汉字、读音或含义<input id="n5KanjiSearch" type="search" value="${esc(n5Search)}" placeholder="日、にち、时间…"></label><p class="hint">先从例词认识汉字。音读、训读列出常见读法，并非全部读法；同一个字在不同词里读音可能不同。按例词读音跟读，再在纸上书写。</p><div class="n5-kanji-grid">${chars.map(k=>`<article class="n5-kanji ${state.course.kanji.includes(k.char)?'done':''}"><b lang="ja">${k.char}</b><h3>${esc(k.meaning)}</h3><p>音读：${esc(k.on||'—')}<br>训读：${esc(k.kun||'—')}</p>${k.words.map(([w,r,m])=>`<div><button class="more" data-speak="${esc(r)}" lang="ja">${esc(w)} ▷</button><small>${esc(r)} · ${esc(m)}</small>${romanLine(r)}</div>`).join('')}<button class="secondary" data-n5kanji="${k.char}">${state.course.kanji.includes(k.char)?'✓ 已认读与书写':'我已认读并在纸上书写 ✓'}</button></article>`).join('')}</div>`;}
function n5SoundView(){return `<div class="sectionhead"><h2>把假名读成自然的词</h2><button class="secondary" data-page="kana">打开完整五十音表 →</button></div><p class="hint">先按拍数慢读，再逐渐连读。这里是文字与合成语音示范；词的重音请配合带真人录音的词典核对。</p>${N5_REFERENCE.pronunciation.map(p=>`<article class="n5-grammar"><h2>${esc(p.title)}</h2><p>${esc(p.rule)}</p>${p.examples.map(([w,r,m])=>`<div class="example"><b lang="ja">${esc(w)}</b>${romanLine(r.includes("・")||r.includes("拍")?w:r,true)}<small>${esc(r)} · ${esc(m)}</small><button class="speak" data-speak="${esc(w)}">▷ 跟读</button></div>`).join('')}</article>`).join('')}`;}
function n5ExamIds(key){const us=key==='final'?N5_UNITS:N5_UNITS.slice((Number(key)-1)*6,Number(key)*6),pick=(ids,n)=>shuffled([...new Set(ids)]).slice(0,n);return key==='final'?[...pick(us.flatMap(u=>u.grammarIds),12),...pick(us.flatMap(u=>u.wordIds),10),...pick(us.flatMap(u=>u.reading.ids),10),...pick(us.flatMap(u=>u.listening.ids),8)]:[...pick(us.flatMap(u=>u.grammarIds),6),...pick(us.flatMap(u=>u.wordIds),6),...pick(us.flatMap(u=>u.reading.ids),4),...pick(us.flatMap(u=>u.listening.ids),4)];}
function n5StartExam(key){if(state.course.exam&&!state.course.exam.submitted){n5Tab='checks';n5Selected=null;go('lessons','N5');toast('先继续或交卷当前复习，再开始新的一组。');return;}state.course.exam={key,ids:n5ExamIds(key),answers:{},submitted:false};n5Tab='checks';n5Selected=null;persist();go('lessons','N5');}
function n5ExamScore(x){return Math.round(x.ids.filter(id=>x.answers[id]===questionById(id).answer).length/x.ids.length*100);}
function n5ChecksView(){const x=state.course.exam;return `<div class="sectionhead"><h2>阶段复习与 N5 结课</h2></div><p class="hint">阶段复习每组 20 题；结课测评 40 题，检查本站课程学习情况。建议先学完对应单元，达到 80% 后继续巩固薄弱项。正确率不换算 JLPT 标准分。</p><div class="n5-check-grid">${['1','2','3','4','final'].map(k=>`<article><h3>${k==='final'?'N5 结课测评':`第 ${(Number(k)-1)*6+1}–${Number(k)*6} 单元复习`}</h3><p>${state.course.checks[k]?`最近 ${state.course.checks[k].score}% · ${state.course.checks[k].date}`:'尚未完成'}</p><button class="primary" data-n5exam="${k}">${k==='final'?'40':'20'} 题 · 开始 →</button></article>`).join('')}</div>${x?`<section class="n5-assessment"><div class="sectionhead"><h2>${x.key==='final'?'N5 结课测评':'阶段复习'}</h2><span>已答 ${Object.keys(x.answers).length} / ${x.ids.length}</span></div>${x.submitted?`<div class="n5-review-score"><b>${n5ExamScore(x)}%</b><p>${n5ExamScore(x)>=80?'✓ 达到本站复习建议要求':'建议回到错题对应单元复习'}</p></div>`:'<p>先完整作答，交卷后查看正确答案。刷新可继续；不会修改独立真题记录。</p>'}${x.ids.map((id,i)=>{const q=questionById(id),a=x.answers[id];return `<article class="n5-question"><span class="label">第 ${i+1} 题 · ${typeNames[q.type]}</span>${q.type==='reading'?`<p class="japanese-text" lang="ja">${esc(q.text)}</p>`:q.type==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放听力</button>${x.submitted?`<details><summary>听力原文</summary><p lang="ja">${esc(q.text)}</p></details>`:''}`:''}<h3>${esc(q.q)}</h3><div class="answers">${q.options.map((o,j)=>`<button data-n5examanswer="${id}" data-value="${j}" aria-pressed="${a===j}" ${x.submitted?'disabled':''} class="${x.submitted&&j===q.answer?'correct':x.submitted&&j===a?'wrong':j===a?'n5-chosen':''}">${esc(o)}</button>`).join('')}</div>${x.submitted?`<p class="feedback">${a===q.answer?'✓ 正确':'✕ 复习'} · ${esc(q.why)}</p>`:''}</article>`;}).join('')}${!x.submitted?'<button class="primary" id="n5ExamSubmit">交卷并查看解析 →</button>':''}</section>`:''}<div class="resource-links"><a href="https://www.jlpt.jp/e/about/levelsummary.html" target="_blank" rel="noopener">JLPT 官方能力说明 ↗</a><button class="secondary" data-page="real">独立官方真题训练 →</button></div>`;}
const lessonsBeforeN5=renderLessons;
renderLessons=function(isGrammar=false){if(level!=='N5'||isGrammar)return lessonsBeforeN5(isGrammar);return title('STEP BY STEP · N5','N5 完整学习路线','五十音前置 → 24 个场景单元 → 分段复习 → 结课检查。随时继续上次所学。')+`<section class="container page-section">${n5Tabs()}${n5Tab==='kanji'?n5KanjiView():n5Tab==='sound'?n5SoundView():n5Tab==='checks'?n5ChecksView():n5Selected?n5UnitView():n5Overview()}</section>`;};
const textsBeforeN5=renderTexts;
renderTexts=function(type){if(level!=='N5')return textsBeforeN5(type);return title(type==='reading'?'READ IN CONTEXT':'LISTEN IN CONTEXT',type==='reading'?'N5 课文阅读':'N5 场景听力','24 个单元，每篇三道理解题。建议先学本单元词汇和语法，再练课文。')+`<section class="container page-section"><p class="hint">${type==='listening'?'场景对话使用系统合成语音，需系统日语语音包。配合独立真题里的官方录音训练。':'短文配有完整假名读音、中文对照和逐题解析。'}</p><div class="n5-unit-grid">${N5_UNITS.map((u,i)=>`<button class="n5-unit-card" data-n5unit="${u.id}" data-openstage="${type}"><span class="label">第 ${i+1} 单元</span><h3>${esc(u[type].title)}</h3><p>${esc(u.goal)}</p><span class="n5-badge">${n5UnitState(u.id).done.includes(type)?'✓ 已完成':'○ 未开始'}</span><span class="more">打开课文与练习 →</span></button>`).join('')}</div><details><summary>入门篇章</summary>${n5LegacyTexts(type)}</details></section>`;};
const planBeforeN5=renderPlan,makeDayBeforeN5=makeStudyDay,runStepBeforeN5=runStep,stepInfoBeforeN5=stepInfo;
makeStudyDay=function(){if(state.plan.start!=='N5'||state.guide.foundation<foundationTotal)return makeDayBeforeN5();const u=n5NextUnit(),s=n5UnitState(u.id),stages=n5Passed()===24?['final']:N5_STAGES.filter(k=>!s.done.includes(k)).slice(0,state.plan.minutes===20?1:state.plan.minutes===40?2:3);const oldWords=lw('N5').filter(w=>!u.wordIds.includes(w.id)&&state.wordReviews[w.id]&&state.wordReviews[w.id].due<=dateKey()).slice(0,5).map(w=>w.id);if(oldWords.length&&n5Passed()<24)stages.push('reviewWords');state.guide.day={date:dateKey(),number:state.guide.number,level:'N5',foundation:foundationTotal,n5Unit:u.id,n5Stages:stages,steps:stages.map(k=>k==='reviewWords'?{kind:'vocab',ids:oldWords,done:false,doneIds:[]}:{kind:'course',ids:[],done:k==='final'&&(state.course.checks.final?.score||0)>=80}),writing:''};persist();return state.guide.day;};
stepInfo=function(t,d){if(t.kind!=='course')return stepInfoBeforeN5(t,d);const k=d.n5Stages[d.steps.indexOf(t)];return{title:`${n5Unit(d.n5Unit).title} · ${N5_STAGE_NAMES[k]}`,desc:k==='review'?'用 10 题检查本单元理解，达到 80% 后通过。':k==='final'?'学完全部单元后，完成 40 题结课测评。':k.startsWith('words')?'回忆词义，再展开、自评。':k==='grammar'?'理解句型，完成三道练习。':k==='reading'?'读课文，回答三道题。':'听对话，回答三道题。',time:k.startsWith('words')?'8–12 分钟':k==='grammar'?'15–25 分钟':k==='review'?'10–15 分钟':k==='final'?'另行安排':'8–12 分钟'};};
runStep=function(i){const d=studyDay(),t=d.steps[i];if(t?.kind!=='course')return runStepBeforeN5(i);guideActive=true;const k=d.n5Stages[i];if(k==='final'){n5StartExam('final');return;}n5Selected=d.n5Unit;n5Stage=k;n5Tab='course';go('lessons','N5');};
function n5SyncDay(){const d=state.guide.day;if(!d?.n5Unit)return;d.steps.forEach((t,i)=>{if(t.kind==='course')t.done=d.n5Stages[i]==='final'?(state.course.checks.final?.score||0)>=80:n5UnitState(d.n5Unit).done.includes(d.n5Stages[i]);});}
const syncBeforeN5=syncStudyDay;
syncStudyDay=function(){n5SyncDay();return syncBeforeN5();};
renderPlan=function(){const d=syncStudyDay();if(!d.n5Unit)return planBeforeN5();const u=n5Unit(d.n5Unit),active=d.steps.findIndex(t=>!t.done),done=d.steps.filter(t=>t.done).length,all=active<0,finished=n5Passed()===24&&(state.course.checks.final?.score||0)>=80;return title('A CLEAR DAILY PATH','今日学习 · N5 单元课程','今天学哪一课、先做什么，都已经安排好。未完成的任务会保留。')+`<section class="container page-section"><div class="study-dashboard"><div><span class="label">第 ${d.number} 学习日 · N5 第 ${N5_UNITS.indexOf(u)+1} 单元</span><h2>${finished?'N5 课程学习与结课检查已完成 ✓':all?'今天的课程任务完成了 ✓':esc(stepInfo(d.steps[active],d).title)}</h2><p>${finished?'继续复习汉字和词卡，或用官方真人录音与真题检查能力。':all?'可以做可选写作、休息，或手动开始下一学习日。':esc(u.goal)}</p><div class="study-meter"><div style="width:${done/d.steps.length*100}%"></div></div><small>本日必修 ${done}/${d.steps.length} · 已通过 ${n5Passed()}/24 单元 · 预算 ${state.plan.minutes} 分钟</small></div><div class="study-action">${finished?'<button class="primary" data-page="real" data-level="N5">检验官方真题 →</button><button class="secondary" id="n5ContinueN4">进入 N4 学习 →</button>':all?'<button class="primary" id="nextStudyDay">开始下一学习日 →</button>':'<button class="primary" id="startStudyStep">'+(done?'继续下一步 →':'开始今天的学习 →')+'</button>'}</div></div><div class="beginner-route">${['五十音与发音','24 单元课程','每六单元复习','N5 结课检查'].map((t,i)=>`<div class="${i===1?'current':''}"><b>0${i+1}</b><span>${t}</span></div>`).join('')}</div><div class="guided-steps">${d.steps.map((t,i)=>`<article class="guided-step ${t.done?'done':i===active?'current':'pending'}"><span class="step-number">${t.done?'✓':i+1}</span><div><span class="step-state">${t.done?'已完成':i===active?'现在做':'下一步'} · ${stepInfo(t,d).time}</span><h3>${esc(N5_STAGE_NAMES[d.n5Stages[i]])}</h3><p>${esc(stepInfo(t,d).desc)}</p></div><button class="${i===active?'primary':'secondary'}" data-guidestep="${i}" ${i>active&&!all?'disabled':''}>${t.done?'再复习':'开始 →'}</button></article>`).join('')}</div><p class="hint">未完成的任务会保留。每天安排 1–3 步，并复习到期词汇。</p>${n5Writing(u)}<div class="toolbar"><button class="secondary" data-n5unit="${u.id}">查看整个单元 →</button><button class="secondary" data-n5tab="kanji">汉字认读与书写 →</button><button class="secondary" data-page="progress">导出学习档案 →</button></div><details class="plan-options"><summary>调整起点、目标与每日时间</summary><form id="planForm" class="plan-settings"><label>开始阶段<select name="start">${LEVELS.map(l=>`<option ${l===state.plan.start?'selected':''}>${l}</option>`).join('')}</select></label><label>目标等级<select name="target">${LEVELS.map(l=>`<option ${l===state.plan.target?'selected':''}>${l}</option>`).join('')}</select></label><label>每天时间<select name="minutes">${[20,40,60].map(n=>`<option value="${n}" ${n===state.plan.minutes?'selected':''}>${n} 分钟</option>`).join('')}</select></label><button class="primary">保存计划 ✓</button></form><p>新设置从下个学习日生效。</p></details>${state.guide.archive.length?`<details class="plan-options"><summary>近期已完成学习日 · ${state.guide.archive.length}</summary>${[...state.guide.archive].reverse().map(x=>`<article class="study-history"><b>第 ${x.number} 学习日 · ${x.date}</b><p>${esc(x.title)}</p></article>`).join('')}</details>`:''}</section>`;};
const archiveBeforeN5=archiveDay;
archiveDay=function(){const d=state.guide.day,name=d?.n5Unit?`N5 · ${n5Unit(d.n5Unit).title} · ${d.n5Stages.map(k=>N5_STAGE_NAMES[k]).join(' / ')}`:null;archiveBeforeN5();if(name)state.guide.archive.at(-1).title=name;};
const progressBeforeN5=renderProgress;
renderProgress=function(){return progressBeforeN5()+`<section class="container page-section"><div class="sectionhead"><h2>N5 单元课程档案</h2><span>通过 ${n5Passed()}/24</span></div><div class="n5-unit-grid">${N5_UNITS.map(u=>`<button class="n5-unit-card" data-n5unit="${u.id}"><h3>${esc(u.title)}</h3><p>${n5Status(u)} · 步骤 ${n5UnitState(u.id).done.length}/6</p><small>复习 ${n5UnitState(u.id).score}% · ${n5UnitState(u.id).draft?'有写作草稿':'未写草稿'}</small></button>`).join('')}</div><p>已认读书写汉字 ${state.course.kanji.length}/${N5_REFERENCE.kanji.length} · N5 结课 ${state.course.checks.final?.score??'未完成'}${state.course.checks.final?'%':''}</p><p class="completion-note">课程与草稿一起导出；真题记录需另行导出。</p>${state.course.legacyDraft?`<details><summary>课程升级前的写作草稿</summary><p lang="ja">${esc(state.course.legacyDraft)}</p></details>`:''}</section>`;};
function n5UpdateWordControls(){const u=n5Unit(n5Selected),s=n5UnitState(u.id),start=n5Stage==='words1'?0:10,ids=u.wordIds.slice(start,start+10),count=ids.filter(id=>s.ratings.includes(id)).length;const progress=$('#n5WordProgress');if(progress)progress.textContent=`已自评 ${count} / ${ids.length} 个${count===ids.length?' · 可以完成本步':''}`;const next=$('#n5NextWord');if(next)next.disabled=count===ids.length;const finish=$('#n5Finish');if(finish)finish.disabled=!n5CanFinish(u,n5Stage);const note=$('.n5-finish p');if(note&&count===ids.length)note.textContent='已完成本组全部词汇自评，确认后继续。';}
function n5FinishStage(){const u=n5Unit(n5Selected),s=n5UnitState(u.id);if(!n5CanFinish(u,n5Stage))return;const first=!s.done.includes(n5Stage);if(first){s.done.push(n5Stage);if(n5Stage==='grammar')u.grammarIds.forEach(markLesson);if(n5Stage==='reading'||n5Stage==='listening'){state.textDone=[...new Set([...state.textDone,...u[n5Stage].ids])];touch(n5Stage);}if(n5Stage==='review')s.score=Math.round(n5Questions(u,'review').filter(id=>s.review[id]===questionById(id).answer).length/10*100);}n5SyncDay();persist();if(guideActive){go('plan','N5');toast('本步已保存，返回今日计划继续。');}else{const next=N5_STAGES[N5_STAGES.indexOf(n5Stage)+1];if(next)n5Stage=next;persist();render(false);toast(first?'课程进度已保存。':'已返回下一步。');}}
document.addEventListener('click',e=>{const summary=e.target.closest('summary'),detail=summary?.parentElement;if(detail?.dataset.expandReading&&!detail.open)speak(detail.dataset.expandReading);const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
 if(d.n5tab){n5Tab=d.n5tab;n5Selected=null;go('lessons','N5');}
 if(d.n5unit){n5Selected=d.n5unit;n5Tab='course';n5Stage=d.openstage||N5_STAGES.find(k=>!n5UnitState(n5Selected).done.includes(k))||'review';go('lessons','N5');}
 if(d.n5stage){stopAudio();n5Stage=d.n5stage;persist();render(false);}
 if(b.id==='n5NextWord'){const ratings=n5UnitState(n5Selected).ratings,card=[...document.querySelectorAll('.n5-word[data-word-id]')].find(el=>!ratings.includes(el.dataset.wordId));if(card){const detail=card.querySelector('details');if(detail&&!detail.open){detail.open=true;speak(detail.dataset.expandReading);}card.scrollIntoView({behavior:'smooth',block:'center'});card.querySelector('summary')?.focus({preventScroll:true});}}
 if(b.id==='n5Back'){n5Selected=null;persist();render(false);}
 if(d.n5rate){const s=n5UnitState(n5Selected),w=words.find(x=>x.id===d.n5rate),old=state.wordReviews[w.id]||{box:0},box=d.value==='1'?(old.last===dateKey()?Math.max(old.box,1):Math.min(old.box+1,6)):0;s.ratings=[...new Set([...s.ratings,w.id])];state.wordReviews[w.id]={box,due:box?afterDays([1,3,7,14,30,60][box-1]):dateKey(),last:dateKey()};if(old.last!==dateKey())touch('vocab');persist();const card=b.closest('.n5-word'),badge=card?.querySelector('.n5-badge');if(badge){badge.textContent=d.value==='1'?'✓ 已记住':'↺ 需巩固';badge.classList.toggle('word-needs-review',d.value!=='1');}card?.querySelectorAll('[data-n5rate]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn===b)));n5UpdateWordControls();}
 if(d.n5answer){const s=n5UnitState(n5Selected),a=Number(d.value),map=d.review?s.review:s.answers;if(map[d.n5answer]!==undefined)return;map[d.n5answer]=a;recordAnswer(questionById(d.n5answer),a);persist();render(false);}
 if(d.n5audio)speak(n5Unit(d.n5audio).listening.text,Number($('#n5Speed')?.value||.95));
 if(b.id==='n5Finish')n5FinishStage();
 if(b.id==='n5Retry'){const u=n5Unit(n5Selected),s=n5UnitState(u.id),map=n5Stage==='review'?s.review:s.answers;n5Questions(u,n5Stage).forEach(id=>delete map[id]);persist();render(false);}
 if(d.n5kanji){state.course.kanji=[...new Set([...state.course.kanji,d.n5kanji])];touch();render(false);}
 if(d.n5exam)n5StartExam(d.n5exam);
 if(d.n5examanswer){const x=state.course.exam;if(!x||x.submitted)return;x.answers[d.n5examanswer]=Number(d.value);persist();b.closest('.answers').querySelectorAll('button').forEach(el=>{el.classList.toggle('n5-chosen',el===b);el.setAttribute('aria-pressed',String(el===b));});const count=$('.n5-assessment .sectionhead span');if(count)count.textContent=`已答 ${Object.keys(x.answers).length} / ${x.ids.length}`;}
 if(b.id==='n5ExamSubmit'){const x=state.course.exam;if(!x||x.submitted)return;if(x.ids.some(id=>x.answers[id]===undefined)){toast('请完成全部题目再交卷，未答进度已保存。');return;}x.submitted=true;x.ids.forEach(id=>recordAnswer(questionById(id),x.answers[id]));state.course.checks[x.key]={score:n5ExamScore(x),date:dateKey()};n5SyncDay();persist();render(false);}
 if(b.id==='n5ContinueN4'){state.plan.start='N4';if(state.plan.target==='N5')state.plan.target='N4';if(state.guide.day?.steps.every(t=>t.done))archiveDay();else state.guide.day=null;persist();go('plan','N4');}
});
document.addEventListener('input',e=>{if(e.target.id==='n5Writing'){const id=n5Selected&&page==='lessons'?n5Selected:studyDay().n5Unit;n5UnitState(id).draft=e.target.value;persist();$('#n5WritingStatus').textContent='草稿已自动保存';}if(e.target.id==='n5KanjiSearch'){n5Search=e.target.value;const focus=e.target.selectionStart;$('#view').innerHTML=renderLessons();const input=$('#n5KanjiSearch');input.focus();input.setSelectionRange(focus,focus);}});
render(false);

function n5LegacyTexts(type){const items=(type==='reading'?readings:listenings).filter(t=>t.level==='N5'&&!t.unit);return items.map(q=>`<article class="text-card"><h3>${esc(q.title)}</h3>${type==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放</button>`:''}<p class="japanese-text" lang="ja">${esc(q.text)}</p><details><summary>查看翻译</summary><p>${esc(q.translation)}</p></details>${answerBlock(q)}<button class="more" data-textdone="${q.id}" disabled>完成并记录 ✓</button></article>`).join('');}
const homeBeforeN5=renderHome;
renderHome=function(){let html=homeBeforeN5();if(level==='N5')html=html.replace(`data-lesson="${nextGrammar('N5').id}">继续语法课`,`data-n5unit="${n5NextUnit().id}">继续 N5 单元课`);return html;};
const vocabBeforeN5=renderVocab;
renderVocab=function(){const html=vocabBeforeN5();return level==='N5'?html.replace('这是各阶段的核心示例词库，完整 JLPT 备考还需扩大词汇量。','N5 词库包含单元词汇和生活主题补充词，属于本站教学选编；可在系统课程里按单元学习。'):html;};
render(false);

// Upgrade an old N5 grammar day to the unit curriculum, preserving completed lessons and its draft.
if(state.guide.day?.level==='N5'&&state.guide.day.foundation>=foundationTotal&&!state.guide.day.n5Unit){const old=state.guide.day;if(old.writing)state.course.legacyDraft=old.writing;if(old.steps.every(t=>t.done))archiveDay();else state.guide.day=null;persist();render(false);}

function mergeN5Course(current,incoming){const a=current||{units:{},kanji:[],checks:{}},b=incoming||{units:{},kanji:[],checks:{}},out={...b,units:{},kanji:[...new Set([...a.kanji,...b.kanji])],checks:{...a.checks,...b.checks},legacyDraft:b.legacyDraft||a.legacyDraft||''};for(const u of N5_UNITS){const x=a.units[u.id],y=b.units[u.id];if(!x&&!y)continue;if(!x||!y){out.units[u.id]=x||y;continue;}out.units[u.id]={...y,done:[...new Set([...x.done,...y.done])],ratings:[...new Set([...x.ratings,...y.ratings])],answers:{...x.answers,...y.answers},review:{...x.review,...y.review},draft:y.draft||x.draft,score:Math.max(x.score,y.score)};}if(a.exam&&!a.exam.submitted)out.exam=a.exam;return out;}
